REBALANCE_EVERY = 10
MIN_WEIGHT, MAX_WEIGHT = 0.02, 0.14
_calls = 0


def ranks(values):
    valid = sorted((s, v) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(valid)
    if n > 1:
        for i, (s, _) in enumerate(valid):
            out[s] = (i + 1.0) / n
    elif n == 1:
        out[valid[0][0]] = 1.0
    return out


def bounded(raw):
    # Water-fill a complete, long-only target without a cash sleeve.
    w = {s: max(float(raw.get(s, 0.0)), 1e-9) for s in UNIVERSE}
    fixed = {}
    active = set(UNIVERSE)
    for _ in range(20):
        left = 1.0 - sum(fixed.values())
        den = sum(w[s] for s in active)
        trial = {s: left * w[s] / den for s in active}
        clipped = False
        for s, x in list(trial.items()):
            if x < MIN_WEIGHT:
                fixed[s] = MIN_WEIGHT; active.remove(s); clipped = True
            elif x > MAX_WEIGHT:
                fixed[s] = MAX_WEIGHT; active.remove(s); clipped = True
        if not clipped:
            fixed.update(trial); break
    if active:
        left = 1.0 - sum(fixed.values())
        den = sum(w[s] for s in active)
        fixed.update({s: left * w[s] / den for s in active})
    total = sum(fixed.values())
    return {s: fixed[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _calls
    _calls += 1
    if _calls != 1 and (_calls - 1) % REBALANCE_EVERY != 0:
        return

    raw = {k: {} for k in FACTORS}
