    w = {s: max(float(raw.get(s, 0.0)), 1e-8) for s in UNIVERSE}
    fixed, active = {}, set(UNIVERSE)
    for _ in range(30):
        left = 1.0 - sum(fixed.values())
        den = sum(w[s] for s in active)
        trial = {s: left * w[s] / den for s in active}
        clipped = False
        for s, value in list(trial.items()):
            if value < MIN_WEIGHT:
