    if active:
        left = 1.0 - sum(fixed.values())
        den = sum(w[s] for s in active)
        fixed.update({s: left * w[s] / den for s in active})
    total = sum(fixed.values())
    return {s: fixed[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _calls
    _calls += 1
    if _calls != 1 and (_calls - 1) % REBALANCE_EVERY:
        return

    raw = {k: {} for k in FACTORS}
