    score = {s: sum(FACTORS[k] * ranks[k][s] for k in FACTORS) for s in UNIVERSE}
    breadth = float(np.mean([r20[s] > 0 for s in r20])) if r20 else 0.5
    defensive = {"XAU", "US10Y", "CN10Y"}
    mean_inv = float(np.mean([1.0 / v for v in vols.values()]))
    target = {}
    for s in UNIVERSE:
        inv = min((1.0 / vols.get(s, np.mean(list(vols.values())))) / mean_inv, 1.5)
        # Sideways/high-risk: keep full investment but rotate modestly to defensives.
        posture = 1.10 if breadth < 0.45 and s in defensive else (0.97 if breadth < 0.45 else 1.0)
        target[s] = max(score[s], 0.05) * (0.97 + 0.03 * inv) * posture
    rebalance_to_weights(bounded(target))

