UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
FACTORS = {"peer5": 0.20, "mom20": 0.16, "clv": 0.16, "lowvol": 0.16,
           "stress": 0.10, "beta5": 0.10, "rev3": 0.07, "beta2": 0.05}
REBALANCE_EVERY = 10
MIN_WEIGHT, MAX_WEIGHT = 0.02, 0.14
_calls = 0


def xrank(values):
    valid = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not valid:
        return out
    for i, (s, _) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def bounded(raw):
    # Water-filling keeps every tradable asset represented and sums exactly to one.
    base = {s: max(float(raw.get(s, 0.0)), 1e-9) for s in UNIVERSE}
    fixed, active = {}, set(UNIVERSE)
    for _ in range(40):
        left = 1.0 - sum(fixed.values())
        den = sum(base[s] for s in active)
        trial = {s: left * base[s] / den for s in active}
        clipped = False
        for s, w in list(trial.items()):
            if w < MIN_WEIGHT:
                fixed[s] = MIN_WEIGHT; active.remove(s); clipped = True
            elif w > MAX_WEIGHT:
                fixed[s] = MAX_WEIGHT; active.remove(s); clipped = True
        if not clipped:
            fixed.update(trial)
            break
    z = sum(fixed.values())
    return {s: fixed.get(s, 0.0) / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _calls
    _calls += 1
    if _calls != 1 and (_calls - 1) % REBALANCE_EVERY != 0:
        return

    raw = {k: {} for k in FACTORS}
    returns, vols, mom = {}, {}, {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=130)
        if df is None or len(df) < 35:
            continue
        df = df.sort_values("date").reset_index(drop=True)
        c = np.asarray(df["close"], dtype=float)
        o = np.asarray(df["open"], dtype=float)
        h = np.asarray(df["high"], dtype=float)
        l = np.asarray(df["low"], dtype=float)
        if np.any(~np.isfinite(c[-35:])) or np.any(c[-35:] <= 0):
            continue
        r = c[1:] / c[:-1] - 1.0
        v = max(float(np.nanstd(r[-20:])), 0.008)
        returns[s], vols[s] = r, v
        mom[s] = c[-1] / c[-21] - 1.0
        span = h[-1] - l[-1]
        raw["clv"][s] = -(c[-1] - o[-1]) / span if np.isfinite(span) and span > 0 else 0.0
        shock = np.clip(abs(r[-1]) / v, 0.5, 2.0)
        raw["lowvol"][s] = -r[-1] / v
        raw["stress"][s] = -r[-1] / v * shock
        raw["mom20"][s] = mom[s] / (v * np.sqrt(20.0) + 0.01)

    if len(returns) < 8:
        return
    for s, r in returns.items():
        peers = [t for t in returns if t != s]
        def cum(t, n):
            return np.prod(1.0 + returns[t][-n:]) - 1.0
        med5 = float(np.median([cum(t, 5) for t in peers]))
        med3 = float(np.median([cum(t, 3) for t in peers]))
        med2 = float(np.median([cum(t, 2) for t in peers]))
        own5, own3, own2 = cum(s, 5), cum(s, 3), cum(s, 2)
        # Lead-lag rewards relative leadership; residual factors mean-revert it.
        raw["peer5"][s] = own5 - med5
        raw["beta5"][s] = -(own5 - med5) / (vols[s] * np.sqrt(5.0) + 0.005)
        raw["rev3"][s] = -(own3 - med3) / (vols[s] * np.sqrt(3.0) + 0.005)
        raw["beta2"][s] = -(own2 - med2) / (vols[s] * np.sqrt(2.0) + 0.005)

    ranks = {k: xrank(v) for k, v in raw.items()}
    score = {s: sum(FACTORS[k] * ranks[k][s] for k in FACTORS) for s in UNIVERSE}
    breadth = np.mean([mom[s] > 0 for s in mom])
    market_vol = float(np.median(list(vols.values())))
    risk = market_vol > 0.018 or breadth < 0.45
    avg_inv = np.mean([1.0 / v for v in vols.values()])
    defensive = {"XAU", "US10Y", "CN10Y"}
    target = {}
    for s in UNIVERSE:
        inv = min((1.0 / vols.get(s, market_vol)) / avg_inv, 1.5)
        tilt = 1.12 if risk and s in defensive else 1.0
        target[s] = max(score[s], 0.05) * (0.85 + 0.15 * inv) * tilt
    rebalance_to_weights(bounded(target))

