def cross_asset_strategy():
    global _day
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE:
        return
    series, vol, mom = {}, {}, {}
    raw = {k: {} for k in FACTORS}
    for s in UNIVERSE:
        d = get_stock_daily_data(symbol=s, days=135)
        if d is None or len(d) < 35: continue
        d = d.sort_values("date").reset_index(drop=True)
        c, o, h, l = [np.asarray(d[k], dtype=float) for k in ("close", "open", "high", "low")]
        r = c[1:]/c[:-1]-1
        if len(r) < 30 or not np.all(np.isfinite(c[-35:])) or np.any(c[-35:] <= 0): continue
        v = max(float(np.nanstd(r[-20:])), .008)
        series[s], vol[s] = r, v; mom[s] = c[-1]/c[-21]-1
        span = h[-1]-l[-1]
        raw["clv"][s] = -(c[-1]-o[-1])/span if np.isfinite(span) and span > 0 else 0
        raw["lowvol1"][s] = -r[-1]/v
