    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out


def bounded_weights(raw):
    # Iterative water-filling keeps all 15 assets invested and within sensible bounds.
    w = {s: max(float(raw.get(s, 1.0)), 1e-10) for s in UNIVERSE}
    fixed = set()
    for _ in range(30):
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1.0 - sum(w[s] for s in fixed)
        base = sum(w[s] for s in free)
        if base <= 0 or not free:
            break
        for s in free:
            w[s] = rem * w[s] / base
        newly = {s for s in free if w[s] < MIN_W or w[s] > MAX_W}
        if not newly:
            break
        for s in newly:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        fixed |= newly
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
