import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
CADENCE = 10
MIN_W, MAX_W = .035, .16
# Current screener ensemble, with deliberately reduced overlap in the shock cluster.
WEIGHTS = {"volume_shock": .16, "vol_state": .14, "intraday": .12,
           "dispersion": .12, "stress": .11, "momentum": .08,
           "reversal10": .08, "rel_strength": .07, "residual": .06,
           "reversal15": .06}
_day = 0
_previous = None


def cs_rank(values, direction=1):
    good = [(s, float(v)) for s, v in values.items() if np.isfinite(v)]
    out = {s: .5 for s in UNIVERSE}
    if not good:
        return out
    good.sort(key=lambda z: z[1], reverse=direction < 0)
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.) / n
    return out


def bounded(raw):
    w = {s: max(float(raw.get(s, 1.)), 1e-12) for s in UNIVERSE}
    fixed = set()
    for _ in range(30):
        free = [s for s in UNIVERSE if s not in fixed]
        rem = 1. - sum(w[s] for s in fixed)
        z = sum(w[s] for s in free)
        for s in free:
            w[s] = rem * w[s] / max(z, 1e-12)
        hit = {s for s in free if w[s] < MIN_W or w[s] > MAX_W}
        if not hit:
            break
        for s in hit:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        fixed |= hit
    z = sum(w.values())
    return {s: w[s] / z for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
    global _day, _previous
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE:
        return
    data = {}
    for s in UNIVERSE:
        df = get_stock_daily_data(symbol=s, days=270)
        if df is None or len(df) < 160:
            continue
        df = df.sort_values("date")
        c = np.asarray(df["close"], float); o = np.asarray(df["open"], float)
        hi = np.asarray(df["high"], float); lo = np.asarray(df["low"], float)
        if np.any(~np.isfinite(c)) or np.any(c <= 0):
            continue
        r = c[1:] / c[:-1] - 1.
        v = np.nan_to_num(np.asarray(df["volume"], float), nan=0.)
        data[s] = {"r": r, "h3": np.prod(1+r[-3:])-1, "h5": np.prod(1+r[-5:])-1,
          "h10": np.prod(1+r[-10:])-1, "h15": np.prod(1+r[-15:])-1,
          "h20": np.prod(1+r[-20:])-1, "h120": np.prod(1+r[-120:])-1,
          "v5": max(np.std(r[-5:]), .006), "v20": max(np.std(r[-20:]), .006),
          "v60": max(np.std(r[-60:]), .006), "vr": np.mean(v[-5:])/max(np.mean(v[-20:]),1e-9),
          "intra": np.nanmean((c[-5:]-o[-5:])/np.maximum(o[-5:],1e-12)),
          "range": np.nanmean((hi[-5:]-lo[-5:])/c[-5:])}
    if len(data) < 10:
        return
    syms = list(data); med = {k: np.median([data[s][k] for s in syms]) for k in ("h3","h5","h10","h15","h20")}
    # SPX is the benchmark for the residual signal; use a safe zero residual if absent.
    bench = data.get("SPX", {}).get("r", np.zeros(269))
    rawf = {k:{} for k in WEIGHTS}
    for s in syms:
        x = data[s]; scale20 = x["v20"]*np.sqrt(20)+.015
        beta = np.cov(x["r"][-60:], bench[-60:])[0,1]/max(np.var(bench[-60:]),1e-8) if s != "SPX" else 1.
        resid = np.sum(x["r"][-10:] - beta*bench[-10:])
        rawf["volume_shock"][s] = (med["h3"]-x["h3"])/(x["v5"]+.01)*np.clip(x["v5"]/x["v60"],.5,2)
        rawf["vol_state"][s] = (med["h5"]-x["h5"])/(scale20)*np.clip(x["v5"]/x["v60"],.6,1.7)
        rawf["intraday"][s] = -x["intra"]/(x["v5"]+.01)
        rawf["dispersion"][s] = (med["h20"]-x["h20"])/scale20
        rawf["stress"][s] = (med["h10"]-x["h10"])/(x["v20"]*np.sqrt(10)+.02)
        # Breadth gate: retain a measured trend sleeve only when most assets trend up.
        rawf["momentum"][s] = x["h20"]/(x["v20"]*np.sqrt(20)+.02)
        rawf["reversal10"][s] = (med["h10"]-x["h10"])/(x["v20"]*np.sqrt(10)+.01)
        rawf["rel_strength"][s] = -x["h20"]/(x["v20"]+.01)
        rawf["residual"][s] = -resid/(x["v20"]*np.sqrt(10)+.015)
        rawf["reversal15"][s] = (med["h15"]-x["h15"])/(x["v20"]*np.sqrt(15)+.012)
    breadth = np.mean([data[s]["h120"] > 0 for s in syms])
    ranks = {k: cs_rank(v) for k,v in rawf.items()}
    if breadth < .50:
        ranks["momentum"] = {s:.5 for s in UNIVERSE}
    score = {s: sum(WEIGHTS[k]*ranks[k].get(s,.5) for k in WEIGHTS) for s in UNIVERSE}
    score = {s:(.50*score[s]+.50*_previous[s]) if _previous is not None else score[s] for s in UNIVERSE}
    _previous = score.copy()
    high_risk = np.median([data[s]["v20"] for s in syms]) > .018 or breadth < .50
    invmean = np.mean([1./data[s]["v20"] for s in syms])
    raw = {}
    for s in UNIVERSE:
        x = data.get(s, {"v20":.02,"h120":0})
        inv = (1./x["v20"])/max(invmean,1e-9) if s in data else 1.
        raw[s] = max(score[s], .12)*(.90+.10*min(inv,1.25))
        if high_risk and s in DEFENSIVE: raw[s] *= 2.2
        if high_risk and x["h120"] < -.10: raw[s] *= .75
    rebalance_to_weights(bounded(raw))

