DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
CADENCE = 10
MIN_W, MAX_W = 0.035, 0.16
# 2028-06-01 Screener ensemble: downside momentum, residual momentum,
# breakout, up-day dominance, and medium excess momentum.
FACTOR_W = (0.38, 0.27, 0.18, 0.10, 0.07)
_day = 0
_previous = None

def rank_map(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    if not good:
        return out
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / len(good)
    return out

def capped_simplex(raw):
    w = {s: max(float(raw.get(s, 1.0)), 1e-10) for s in UNIVERSE}
    fixed = set()
    for _ in range(60):
        free = [s for s in UNIVERSE if s not in fixed]
        remaining = 1.0 - sum(w[s] for s in fixed)
        total = sum(w[s] for s in free)
        for s in free:
            w[s] = remaining * w[s] / max(total, 1e-12)
        hit = [s for s in free if w[s] < MIN_W or w[s] > MAX_W]
        if not hit:
            break
        for s in hit:
            w[s] = MIN_W if w[s] < MIN_W else MAX_W
        fixed.update(hit)
    total = sum(w.values())
    return {s: w[s] / total for s in UNIVERSE}

@register_hook
def cross_asset_strategy():
    global _day, _previous
    _day += 1
    if _day != 1 and (_day - 1) % CADENCE != 0:
        return
    data = {}
    for symbol in UNIVERSE:
        df = get_stock_daily_data(symbol=symbol, days=260)
        if df is None or len(df) < 80:
            continue
        close = np.asarray(df.sort_values("date")["close"], dtype=float)
        if np.any(~np.isfinite(close)) or np.any(close <= 0):
            continue
        ret = close[1:] / close[:-1] - 1.0
        vol = max(float(np.std(ret[-20:])), 0.006)
        downside = max(float(np.sqrt(np.mean(np.minimum(ret[-20:], 0.0) ** 2))), 0.006)
        r20 = float(np.prod(1.0 + ret[-20:]) - 1.0)
        r60 = float(np.prod(1.0 + ret[-60:]) - 1.0)
        prior60 = close[-61:-1]
        data[symbol] = {
            "vol": vol,
            "down": r20 / downside,
            "r20": r20,
            "breakout": (close[-1] / max(np.max(prior60), 1e-12) - 1.0) / max(vol * np.sqrt(60), .01),
            "up": float(np.mean(ret[-30:] > 0)),
            "medium": r60 / max(vol * np.sqrt(60), .01),
        }
    if len(data) < 10:
        return
    # Cross-sectional median is a robust market proxy for residual momentum.
    median20 = float(np.median([x["r20"] for x in data.values()]))
    for x in data.values():
        x["residual"] = x["r20"] - median20
    factors = ["down", "residual", "breakout", "up", "medium"]
    ranks = [rank_map({s: x[f] for s, x in data.items()}) for f in factors]
    score = {s: sum(FACTOR_W[i] * ranks[i][s] for i in range(5)) for s in UNIVERSE}
