    raw = {}
    for s in UNIVERSE:
        x = data.get(s, {"vol": median_vol, "medium": 0.0})
        vol_damp = np.clip((1.0 / x["vol"]) / max(inv_avg, 1e-12), 0.70, 1.30)
        raw[s] = max(score[s], 0.05) * (0.84 + 0.16 * vol_damp)
        if high_risk and s in DEFENSIVE:
            raw[s] *= 2.0
        if high_risk and s not in DEFENSIVE and x["medium"] < -0.08:
            raw[s] *= 0.75
    rebalance_to_weights(capped_simplex(raw))

