DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
CADENCE = 10
MIN_W, MAX_W = 0.04, 0.18
# Current seven-factor screener ensemble; directions are all positive.
FACTORS = ("volstate", "failure", "dispersion", "lowvol", "volrev", "residual", "consistency")
FACTOR_W = (0.25, 0.22, 0.16, 0.10, 0.10, 0.09, 0.08)
_day = 0
_previous = None


def cs_rank(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: 0.5 for s in UNIVERSE}
    n = len(good)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / max(n, 1)
    return out


def project_weights(raw):
    # Simple bounded projection, preserving the complete 15-asset target.
    w = {s: max(float(raw.get(s, 0.0)), 1e-12) for s in UNIVERSE}
    fixed = {}
    for _ in range(40):
        free = [s for s in UNIVERSE if s not in fixed]
        left = 1.0 - sum(fixed.values())
        z = sum(w[s] for s in free)
        for s in free:
            w[s] = left * w[s] / max(z, 1e-12)
        hits = [s for s in free if w[s] < MIN_W or w[s] > MAX_W]
        if not hits:
            break
        for s in hits:
            fixed[s] = MIN_W if w[s] < MIN_W else MAX_W
            w[s] = fixed[s]
    z = sum(w.values())
    return {s: w[s] / max(z, 1e-12) for s in UNIVERSE}


