    n = max(len(good), 1)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / n
    return out


def bounded_weights(raw):
    # Project positive scores to a complete, full-investment vector.
    lo, hi = .04, .18
    remaining = set(UNIVERSE); fixed = {}
    vals = {s: max(float(raw.get(s, 1.0)), 1e-10) for s in UNIVERSE}
    for _ in range(20):
        rem = 1.0 - sum(fixed.values())
        z = sum(vals[s] for s in remaining)
        provisional = {s: rem * vals[s] / max(z, 1e-12) for s in remaining}
        low = [s for s in remaining if provisional[s] < lo]
        high = [s for s in remaining if provisional[s] > hi]
        if not low and not high:
            fixed.update(provisional)
            break
        for s in low:
            fixed[s] = lo
            remaining.remove(s)
        for s in high:
            fixed[s] = hi
            remaining.remove(s)
    if remaining:
        rem = 1.0 - sum(fixed.values())
        z = sum(vals[s] for s in remaining)
        fixed.update({s: rem * vals[s] / max(z, 1e-12) for s in remaining})
