import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
DEFENSIVE = {"XAU", "US10Y", "CN10Y"}
RISKY = {"BTC", "ETH", "WTI", "COPPER"}
# Screener quality/IC-tilted ensemble; eight active factors, all long-direction ranks.
FACTORS = {"volstate": .22, "failure": .18, "dispersion_rev": .15,
           "beta_mom": .13, "consistency": .11, "relative": .10,
           "break120": .06, "downside_mom": .05}
CADENCE = 10
_previous = None
_day = 0


def ranks(values):
    good = sorted((s, float(v)) for s, v in values.items() if np.isfinite(v))
    out = {s: .5 for s in UNIVERSE}
    n = max(len(good), 1)
    for i, (s, _) in enumerate(good):
        out[s] = (i + 1.0) / n
    return out


def bounded_weights(raw):
    # Full investment across exactly the tradable universe; no cash sleeve.
    lo, hi = .04, .18
    remaining, fixed = set(UNIVERSE), {}
    vals = {s: max(float(raw.get(s, 1.0)), 1e-10) for s in UNIVERSE}
    for _ in range(30):
        rem = 1.0 - sum(fixed.values())
        z = sum(vals[s] for s in remaining)
        provisional = {s: rem * vals[s] / max(z, 1e-12) for s in remaining}
        low = [s for s in remaining if provisional[s] < lo]
        high = [s for s in remaining if provisional[s] > hi]
        if not low and not high:
            fixed.update(provisional)
            break
        for s in low:
            fixed[s] = lo; remaining.remove(s)
        for s in high:
            fixed[s] = hi; remaining.remove(s)
    if remaining:
        rem = 1.0 - sum(fixed.values())
        z = sum(vals[s] for s in remaining)
        fixed.update({s: rem * vals[s] / max(z, 1e-12) for s in remaining})
    total = sum(fixed.values())
    return {s: fixed.get(s, 0.0) / max(total, 1e-12) for s in UNIVERSE}


@register_hook
def cross_asset_strategy():
