        v60 = max(float(np.std(ret[-60:])), .006)
        r20 = float(np.prod(1.0 + ret[-20:]) - 1.0)
        r30 = float(np.prod(1.0 + ret[-30:]) - 1.0)
        neg = ret[-30:][ret[-30:] < 0]
