            "relative": r20 / v20, "downside_mom": r30 / down,
            "break120": close[-1] / max(close[-121:-1]) - 1.0}

    if len(data) < 10:
        return
    market = data.get("000300.SH", data.get("SPX"))
    if market is None:
        return
