    if _previous is not None:
        score = {s: .70 * score[s] + .30 * _previous[s] for s in UNIVERSE}
    _previous = score.copy()

    vols = [x["v20"] for x in data.values()]
    median_vol = float(np.median(vols))
    breadth = float(np.mean([x["consistency"] > 0 for x in data.values()]))
    stressed = median_vol > .015 or float(np.prod(1.0 + mr) - 1.0) < -.06 or breadth < .40
    inv_mean = float(np.mean([1.0 / max(x["v20"], .006) for x in data.values()]))
    raw = {}
    for symbol in UNIVERSE:
        x = data.get(symbol); vol = x["v20"] if x else median_vol
        damping = np.clip((1.0 / max(vol, .006)) / max(inv_mean, 1e-12), .78, 1.10)
        raw[symbol] = max(score[symbol], .02) * (.88 + .12 * damping)
        if stressed:
            raw[symbol] *= 2.35 if symbol in DEFENSIVE else (.25 if symbol in RISKY else .72)
        else:
            raw[symbol] *= 1.08 if symbol in DEFENSIVE else (.90 if symbol in RISKY else 1.0)

