import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, rebalance_to_weights
UNIVERSE=["000300.SH","SPX","HSI","N225","SX5E","000688.SH","SOX","NDX","XAU","COPPER","WTI","BTC","ETH","US10Y","CN10Y"]
DEFENSIVE={"XAU","US10Y","CN10Y"}; RISKY={"BTC","ETH","WTI","COPPER"}
FACTOR_IDS=["miner_2_20280907_breakout_failure_reversal","miner_3_20270211_volstate_reversal_3d","miner_2_20270603_medium_dispersion_reversal","miner_2_20280615_volmanaged_consistency30","miner_1_20280601_relative_strength20","miner_3_20280601_beta_residual_momentum20","miner_3_20280504_downside_adjusted_momentum20"]
FACTOR_WEIGHTS=[.30,.20,.16,.14,.10,.06,.04]; FACTOR_DIRECTIONS=[1]*7; CADENCE=10; _day=0; _previous=None
def rank(vals):
    good=sorted((s,v) for s,v in vals.items() if np.isfinite(v)); out={s:.5 for s in UNIVERSE}
    for i,(s,_) in enumerate(good): out[s]=(i+1.)/len(good)
    return out
def cap_weights(raw):
    w=np.array([max(float(raw.get(s,0)),1e-8) for s in UNIVERSE]); w/=w.sum()
    for _ in range(30):
        over=w>.25
        if not over.any(): break
        excess=float((w[over]-.25).sum()); w[over]=.25; w[~over]+=excess*w[~over]/max(float(w[~over].sum()),1e-12)
    w=np.maximum(w,.02); return dict(zip(UNIVERSE,(w/w.sum()).tolist()))
@register_hook
def cross_asset_strategy():
    global _day,_previous
    _day+=1
    if _day!=1 and (_day-1)%CADENCE!=0: return
    d={}
    for s in UNIVERSE:
        df=get_stock_daily_data(symbol=s,days=300)
        if df is None or len(df)<150: continue
        c=np.asarray(df.sort_values("date")["close"],float)[:-1]
        if len(c)<125 or np.any(~np.isfinite(c)) or np.any(c<=0): continue
        r=c[1:]/c[:-1]-1; v20=max(float(np.std(r[-20:])),.006); v60=max(float(np.std(r[-60:])),.006)
        ret3=float(np.prod(1+r[-3:])-1); ret5=float(np.prod(1+r[-5:])-1); ret20=float(np.prod(1+r[-20:])-1); ret30=float(np.prod(1+r[-30:])-1)
        atr=max(float(np.mean(np.abs(np.diff(c[-11:]))/c[-11:-1])),.006); neg=r[-20:][r[-20:]<0]; down=max(float(np.std(neg)) if len(neg)>1 else v20,.006)
        d[s]={"r":r,"vol":v20,"ret20":ret20,"ret30":ret30,"volstate":-ret3*(.65+.70*v20),"failure":((c[-1]/max(c[-60:])-1)-(c[-1]/max(c[-20:])-1))/atr,"dispersion":-ret5/v60,"consistency":ret30*(.5+float(np.mean(r[-30:]>0)))/v20,"relative":ret20,"downside":ret20/down}
    if len(d)<10:return
    br=d.get("000300.SH",d.get("SPX"))["r"]
    for x in d.values():
        n=min(60,len(x["r"]),len(br)); ar=x["r"][-n:]; b=br[-n:]; beta=float(np.cov(ar,b,ddof=0)[0,1])/max(float(np.var(b)),1e-8); x["betares"]=float(np.sum(ar[-20:]-beta*b[-20:]))
    disp=float(np.std([x["ret20"] for x in d.values()]))
    for x in d.values(): x["dispersion"]*=np.clip(1+.30*np.tanh(disp/.03),.70,1.30)
    names=["failure","volstate","dispersion","consistency","relative","betares","downside"]; rr={n:rank({s:x[n] for s,x in d.items()}) for n in names}
    score={s:sum(w*rr[n][s] for w,n in zip(FACTOR_WEIGHTS,names)) for s in UNIVERSE}
    if _previous is not None: score={s:.8*score[s]+.2*_previous[s] for s in UNIVERSE}
    _previous=score.copy(); med=float(np.median([x["vol"] for x in d.values()])); breadth=float(np.mean([x["ret30"]>0 for x in d.values()])); stressed=med>.015 or float(np.prod(1+br[-20:])-1)<-.06 or breadth<.40
    inv=float(np.mean([1/max(x["vol"],.006) for x in d.values()])); raw={}
    for s in UNIVERSE:
        vol=d.get(s,{"vol":med})["vol"]; damp=np.clip((1/max(vol,.006))/max(inv,1e-12),.70,1.15); tilt=(2.60 if s in DEFENSIVE else .18 if s in RISKY else .60) if stressed else (1.20 if s in DEFENSIVE else .82 if s in RISKY else 1.)
        raw[s]=max(score[s],.03)*(.85+.15*damp)*tilt
    target=cap_weights(raw); forecast={s:float(np.clip((score[s]-.5)*.06,-.03,.03)) for s in UNIVERSE}; rebalance_to_weights(target,forecast_returns=forecast,factor_ids=FACTOR_IDS)

